def section(heading,body,kind='guidance',source_url=''):
    return dict(heading=heading,body=body,kind=kind,source_url=source_url)

def add(model,title,**kwargs):
    return model.objects.get_or_create(slug=slugify(title),defaults=dict(title=title,published=True,**kwargs))[0]

